<?php include 'config.php'; admin_only(); $message='';$type=''; $available=mysqli_query($conn,"SELECT book_id,book_name,author FROM books WHERE status='Available' ORDER BY book_name"); $members=mysqli_query($conn,'SELECT username FROM students ORDER BY username'); if(isset($_POST['issue'])){$id=$_POST['book_id'];$student=$_POST['student'];if(!$id||!$student){$message='Choose both a book and a member.';$type='error';}else{$check=mysqli_prepare($conn,"SELECT book_id FROM books WHERE book_id=? AND status='Available'");mysqli_stmt_bind_param($check,'s',$id);mysqli_stmt_execute($check);if(!mysqli_num_rows(mysqli_stmt_get_result($check))){$message='This book is no longer available.';$type='error';}else{$insert=mysqli_prepare($conn,'INSERT INTO issue_book (book_id,student_name,issue_date) VALUES (?,?,CURDATE())');mysqli_stmt_bind_param($insert,'ss',$id,$student);mysqli_stmt_execute($insert);$update=mysqli_prepare($conn,"UPDATE books SET status='Issued' WHERE book_id=?");mysqli_stmt_bind_param($update,'s',$id);mysqli_stmt_execute($update);$message='Book issued successfully.';$type='success';}}} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Issue book | LibraryHub</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><div class="app-shell"><main class="form-page"><section class="form-card"><a class="btn secondary" href="dashboard.php"><i class="fa-solid fa-arrow-left"></i> Dashboard</a><p class="eyebrow" style="margin-top:25px">Circulation desk</p><h1>Issue a book</h1><p>Assign an available title to a library member.</p><?php if($message): ?><div class="notice <?php echo $type; ?>"><?php echo e($message); ?></div><?php endif; ?><form method="post"><label>Available book</label><select name="book_id" required><option value="">Select a title</option><?php while($book=mysqli_fetch_assoc($available)): ?><option value="<?php echo e($book['book_id']); ?>">#<?php echo e($book['book_id']); ?> — <?php echo e($book['book_name']); ?> by <?php echo e($book['author']); ?></option><?php endwhile; ?></select><label>Member</label><select name="student" required><option value="">Select a student</option><?php while($member=mysqli_fetch_assoc($members)): ?><option value="<?php echo e($member['username']); ?>"><?php echo e($member['username']); ?></option><?php endwhile; ?></select><div class="form-actions"><button class="btn" name="issue"><i class="fa-solid fa-arrow-right"></i> Issue book</button><a class="btn secondary" href="viewbook.php">Browse catalog</a></div></form></section></main></div></body></html>
